"""OpenTelemetry instrumentation shared by every Copilot v2 agent.

Copilot v2 has two agents — the interactive chat agent and the auto-analysis
agent — exporting to the same Langfuse project. They must agree on span format,
so the settings live here rather than being restated at each construction site.

Deliberately a leaf: it holds no agent-specific knowledge and imports nothing
from the runtime package, so the analysis path can reach it without dragging in
the chat agent's dependencies (the classifier, the thread store, the document
search and plan toolsets).

The agent *name* is not set here. It is passed to ``Agent(name=...)`` by each
caller, which is what distinguishes their spans.
"""

from __future__ import annotations

try:
    from pydantic_ai.capabilities.instrumentation import Instrumentation
    from pydantic_ai.models.instrumented import InstrumentationSettings
except ImportError as exc:
    raise ImportError(
        "pydantic-ai-slim is required for Copilot v2. "
        "Install with: pip install rasa-pro[copilot-v2]"
    ) from exc

from rasa.builder.telemetry.langfuse_integration.constants import (
    COPILOT_V2_INSTRUMENTATION_VERSION,
)


def build_instrumentation() -> Instrumentation:
    """Build the OpenTelemetry instrumentation capability for a Copilot v2 agent.

    Settings are stated explicitly rather than left to pydantic-ai's defaults:
    each one changes what reaches Langfuse, so a reviewer should not have to
    know a default to know what the turn exports.
    """
    return Instrumentation(
        settings=InstrumentationSettings(
            version=COPILOT_V2_INSTRUMENTATION_VERSION,
            # Prompts, completions, and tool arguments are recorded. This is
            # parity with v1, which already sends the user's text, the copilot
            # chat history, and tracker context to the same Langfuse project —
            # not a new exposure. Neither path masks content today.
            include_content=True,
            # The run span and every model-request span would otherwise each
            # carry ``gen_ai.usage.*``. A backend that aggregates attributes
            # across a parent/child pair then double-counts the turn's tokens;
            # this renames the run span's copy to ``gen_ai.aggregated_usage.*``.
            use_aggregated_usage_attribute_names=True,
        )
    )
